import '../styles/App.css';
import TodoItem from './check_todo';
/*import Todolist from './todolist'*/

/*function App() {
  return (
    <div> <Todolist /> <TodoItem /></div>
  )
}*/
import React, { useState } from 'react';

function App() {
  const [todos, setTodos] = useState([
    { id: 1, text: 'Faire les courses', completed: false },
    { id: 2, text: 'Réparer la voiture', completed: true },
  ]);

  const handleToggleComplete = (id, newCompletedState) => {
    setTodos(
      todos.map((todo) =>
        todo.id === id ? { ...todo, completed: newCompletedState } : todo
      )
    );
  };

  return (
    <div>
      <h1>Ma liste de tâches</h1>
      <ul>
        {todos.map((todo) => (
          <TodoItem
            key={todo.id}
            todo={todo}
            onToggleComplete={handleToggleComplete}
          />
        ))}
      </ul>
    </div>
  );
}

export default App;
